import 'dart:convert';

import 'package:flutter/services.dart';

import '../localization/app_localizations.dart';

/// Port of `src/data/parallaxScenes.ts`. The scene list (ids, names, absolute
/// R2 image URLs, fgHeight, wholeMove and the per-language Holy-Cross artwork)
/// is generated by `bun scripts/export-data-flutter.mjs` so the Flutter app and
/// the web app always point at the exact same assets.
class ParallaxScene {
  const ParallaxScene({
    required this.id,
    required this.name,
    required this.bg,
    required this.bgCard,
    required this.fg,
    required this.variant,
    required this.fgHeight,
    required this.wholeMove,
    required this.fgByLang,
    required this.fgCardByLang,
  });

  final String id;
  final String name;
  final String bg;
  final String bgCard;
  final String fg;
  final String variant;
  final double fgHeight;
  final bool wholeMove;
  final Map<String, String> fgByLang;
  final Map<String, String> fgCardByLang;

  /// Localized scene name — same `px.scene.<id>` key the web app uses.
  String get localizedName => tc('px.scene.$id') ?? name;

  /// `sceneFg()` — full-size foreground in the current language.
  String fgFor([String? lang]) => fgByLang[lang ?? L10n.current.lang] ?? fg;

  /// `sceneFgCard()` — small optimised foreground for rail cards/previews.
  String fgCardFor([String? lang]) =>
      fgCardByLang[lang ?? L10n.current.lang] ?? fg;

  static ParallaxScene fromJson(Map<String, dynamic> j) => ParallaxScene(
    id: j['id'] as String,
    name: j['name'] as String,
    bg: j['bg'] as String,
    bgCard: j['bgCard'] as String? ?? j['bg'] as String,
    fg: j['fg'] as String? ?? '',
    variant: j['variant'] as String? ?? 'full',
    fgHeight: (j['fgHeight'] as num?)?.toDouble() ?? 0,
    wholeMove: j['wholeMove'] == true,
    fgByLang: Map<String, String>.from(j['fgByLang'] as Map? ?? const {}),
    fgCardByLang: Map<String, String>.from(
      j['fgCardByLang'] as Map? ?? const {},
    ),
  );
}

class ParallaxScenes {
  ParallaxScenes._();

  static List<ParallaxScene>? _cache;

  static List<ParallaxScene> get cached => _cache ?? const [];

  static Future<List<ParallaxScene>> load() async {
    if (_cache != null) return _cache!;
    final raw = await rootBundle.loadString('assets/data/parallax_scenes.json');
    _cache = (jsonDecode(raw) as List)
        .map((e) => ParallaxScene.fromJson(e as Map<String, dynamic>))
        .toList();
    return _cache!;
  }

  static ParallaxScene? byId(String id) {
    for (final s in cached) {
      if (s.id == id) return s;
    }
    return null;
  }
}
